import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Calculate the last day of the month for a given date.
 * @param {string} dateStr - Date in YYYY-MM-DD format
 * @returns {string} Last day of the month in YYYY-MM-DD format
 */
function lastDayOfMonth(dateStr) {
  const [year, month] = dateStr.split('-');
  const nextMonth = String(parseInt(month) + 1).padStart(2, '0');
  const nextMonthFirstDay = `${year}-${nextMonth}-01`;
  return addDays(nextMonthFirstDay, -1);
}

/**
 * Calculate the due date based on payment terms.
 * @param {string} issueDate - Issue date in YYYY-MM-DD format
 * @param {string} terms - Payment terms: 'NET14', 'NET30', or 'EOM'
 * @returns {string} Due date in YYYY-MM-DD format
 */
function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    return lastDayOfMonth(issueDate);
  }
  return null;
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }>, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize and validate customer
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Validate issueDate
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate and calculate due date based on terms
  const validTerms = ['NET14', 'NET30', 'EOM'];
  if (!validTerms.includes(terms)) {
    return fail('TERMS_INVALID');
  }
  const dueDate = calculateDueDate(issueDate, terms);

    qty: line.qty,
    unitPrice: product.unitPrice,
    vatRate: product.vatRate,
    discountPercent,
  });
}

return ok({
  customerId: normalizedCustomerId,
  issueDate,
  status: 'draft',
  lines: enrichedLines,
  terms,
  dueDate,
});
